BEGIN;
CREATE TABLE IF NOT EXISTS screening_tenants(id UUID PRIMARY KEY,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS screening_members(tenant_id UUID REFERENCES screening_tenants(id),user_id INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN('owner','data_steward','analyst','supervisor','redress_officer','viewer')),active BOOLEAN NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS screening_idempotency(actor_id INTEGER NOT NULL,key TEXT NOT NULL,response JSONB NOT NULL,PRIMARY KEY(actor_id,key));
CREATE TABLE IF NOT EXISTS screening_imports(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES screening_tenants(id),source_system TEXT NOT NULL,legal_authority TEXT NOT NULL,content_checksum TEXT NOT NULL,data_as_of TIMESTAMPTZ NOT NULL,idempotency_key TEXT NOT NULL,created_by INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('received','validated','rejected','superseded')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS screening_subjects(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES screening_tenants(id),subject_reference TEXT NOT NULL,document_token TEXT NOT NULL,nationality TEXT,processing_authority TEXT NOT NULL,retention_until DATE NOT NULL,created_by INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,document_token));
CREATE TABLE IF NOT EXISTS screening_alerts(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES screening_tenants(id),subject_id BIGINT NOT NULL REFERENCES screening_subjects(id),source_import_id BIGINT NOT NULL REFERENCES screening_imports(id),candidate_reference TEXT NOT NULL,signals JSONB NOT NULL,score NUMERIC(5,4) NOT NULL CHECK(score BETWEEN 0 AND 1),state TEXT NOT NULL CHECK(state IN('pending_human_review','confirmed_match','false_positive','needs_information')),idempotency_key TEXT NOT NULL,created_by INTEGER NOT NULL,adjudicated_by INTEGER,adjudication_reason TEXT,adjudicated_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS screening_decisions(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES screening_tenants(id),alert_id BIGINT NOT NULL REFERENCES screening_alerts(id),decision TEXT NOT NULL,reason TEXT NOT NULL,legal_authority TEXT NOT NULL,decided_by INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS screening_redress(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES screening_tenants(id),subject_id BIGINT NOT NULL REFERENCES screening_subjects(id),alert_id BIGINT REFERENCES screening_alerts(id),statement TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('submitted','under_review','resolved')),created_by INTEGER NOT NULL,resolution TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS screening_access_history(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES screening_tenants(id),actor_id INTEGER NOT NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,legal_reason TEXT NOT NULL,request_id TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS screening_alert_tenant_state_idx ON screening_alerts(tenant_id,state);
CREATE INDEX IF NOT EXISTS screening_history_tenant_time_idx ON screening_access_history(tenant_id,created_at DESC);
COMMIT;
